fn solve(n: i8, s: Vec<char>) -> i8 {
    // x and y track our current coordinates.
    let mut x: i8 = 0;
    let mut y: i8 = 0;

    // last_region: 0 = border (x == y), 1 = Region A (x > y), 2 = Region B (y > x)
    // Initially, we're on the border at (0, 0), so last_region = 0.
    let mut last_region: i8 = 0;
    let mut transitions: i8 = 0;

    for &c in &s {
        // Apply the move.
        if c == 'U' {
            y += 1;
        } else if c == 'R' {
            x += 1;
        } else {
            // According to the problem statement, there are no other move types.
            continue;
        }

        // Determine the current region.
        let current_region = if x > y {
            1 // Region A
        } else if y > x {
            2 // Region B
        } else {
            0 // Border
        };

        // Only consider transitions when we're strictly in A or B.
        if current_region != 0 {
            if last_region == 0 {
                // First time leaving the border into a region: set last_region but do not count.
                last_region = current_region;
            } else if current_region != last_region {
                // We have entered a different region than last time: count a transition.
                transitions += 1;
                last_region = current_region;
            }
        }
        // If current_region == 0 (border), do nothing; we remember last_region for when we leave.
    }

    transitions
}